INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N058-01','CN0139','W03S18','水量与危废边界','§2.7/2.9.2/2.9.4','全项目30168.26m³/a为报告汇总，其中冷凝回用4554.45、纳管25613.81；6项纳管分股相加恰为25613.81。另清洗冷凝25.92未单独纳入汇总，可能重叠，保留待核；报告§2.7开头称无需清洗，但后文给32m³/a清洗用水；高盐原水量及盐种未公开。浓缩盐液5042.91t/a为危废质量而非m³；原表回用水金属浓度是物料衡算非监测。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N058-02','CN0139','W03S18','设备与经济','§2.2表2.2-2、§2.7','MVR设计2m³/h及投资185万元、输送管道20万元，环保总投资928万元。事故水提升池50m³、事故罐1250m³、初雨池50m³；不是站处理量。纯水RO 5m³/h、70%制水率；纯水膜不计作废水膜。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N058-03','CN0139','W03S18','外部共享污水站','§2.9.3.2','凤凰污水厂2018批复4万m³/d；2021建成一期2万m³/d、8月调试；预处理、水解、厌氧、两级A/O、絮凝沉淀、过滤、消毒，尾水入乌河。历史引用为园区共享站，不能归作三瑞自建或专属容量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N058-04','CN0309','S058-04','组织职责','2026H1报告检索摘录','生产部负责工艺质量成本持续改善；技术部负责技术工艺难题和规程；EHS部监督安全环保；品保部负责检验。销售由全资子公司统一承担。未公开EHS负责人直接工作联系方式，不将售后或技术热线认定为EHS直线。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N058-05','CN0202','S058-05','生产动态','2026-11公司新闻','公司披露眉山基地铜系、镍系催化剂稳定生产及出口发货，不能推断污水系统实际运行或产量。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N058-06','CN0202','S058-06','公开部门负责人线索','学院2026校企洽谈会','报道列西南化工研究设计院催化剂事业部副总经理曾旭、综合部主任文华清；为报道时点职务，非厂区EHS负责人。无公开直联，不造联系方式或将集团热线与个人绑定。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N058-07','CN0309','S058-02','公开设备采购与技术联系岗位','官网总部联系方式','官网列设备采购吴先生、王先生，技术咨询王先生、栾女士，均为明确业务角色；本轮仅录办公热线、机构工作邮箱，个人关联手机不转录；采购总线可申请转接设备部门。姓氏不推断全名。','WEB_COMPANY','WEB_TEXT','2026-11-28');
